package com.berling.marketplace.ui.screens.home\n\nimport android.content.Context\nimport androidx.lifecycle.viewModelScope\nimport com.berling.marketplace.data.local.entities.ProductEntity\nimport com.berling.marketplace.data.repository.EnhancedProductRepository\nimport com.berling.marketplace.data.repository.ProductRepository\nimport com.berling.marketplace.ui.screens.BaseViewModel\nimport com.berling.marketplace.ui.screens.UiState\nimport com.berling.marketplace.utils.CacheManager\nimport dagger.hilt.android.lifecycle.HiltViewModel\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.launch\nimport javax.inject.Inject\n\n@HiltViewModel\nclass HomeViewModelEnhanced @Inject constructor(\n    private val productRepository: ProductRepository,\n    private val enhancedProductRepository: EnhancedProductRepository,\n    private val context: Context\n) : BaseViewModel() {\n\n    private val _productsState = MutableStateFlow<UiState<List<ProductEntity>>>(UiState.Loading)\n    val productsState: StateFlow<UiState<List<ProductEntity>>> = _productsState\n\n    private val _selectedCategory = MutableStateFlow(\"Popular\")\n    val selectedCategory: StateFlow<String> = _selectedCategory\n\n    private val _isLoadingMore = MutableStateFlow(false)\n    val isLoadingMore: StateFlow<Boolean> = _isLoadingMore\n\n    private val _currentPage = MutableStateFlow(0)\n    val currentPage: StateFlow<Int> = _currentPage\n\n    private val _cacheSize = MutableStateFlow(0L)\n    val cacheSize: StateFlow<Long> = _cacheSize\n\n    private var allProducts = mutableListOf<ProductEntity>()\n    private val pageSize = 20\n\n    init {
        loadProductsWithCache()
        observeProductsRealtime()
        updateCacheSize()
    }

    /**
     * Observe products table in real-time
     */
    private fun observeProductsRealtime() {
        viewModelScope.launch {
            try {
                productRepository.observeProductsRealtime().collect { updatedProduct ->
                    // Update the products list when a new product is added or updated
                    val currentList = allProducts.toMutableList()
                    val index = currentList.indexOfFirst { it.id == updatedProduct.id }
                    
                    if (index != -1) {
                        currentList[index] = updatedProduct
                    } else {
                        // Add to the beginning of the list for "newest first" behavior
                        currentList.add(0, updatedProduct)
                    }
                    
                    allProducts = currentList
                    _productsState.emit(UiState.Success(allProducts.toList()))
                    logInfo("Real-time update: Product ${updatedProduct.title} received")
                }
            } catch (e: Exception) {
                logError("Error in real-time observation: ${e.message}")
            }
        }
    }\n\n    /**\n     * Load products with caching support\n     */\n    fun loadProductsWithCache(forceRefresh: Boolean = false) {\n        viewModelScope.launch {\n            _productsState.emit(UiState.Loading)\n            _currentPage.emit(0)\n            allProducts.clear()\n\n            try {\n                // Check if cache is valid\n                if (!forceRefresh && CacheManager.hasCachedProducts(context)) {\n                    logInfo(\"Loading products from cache\")\n                    // Load from cache first\n                    productRepository.getAllProducts().collect { products ->\n                        allProducts.clear()\n                        allProducts.addAll(products)\n                        _productsState.emit(UiState.Success(products))\n                    }\n                } else {\n                    // Load from remote with caching\n                    logInfo(\"Loading products from Supabase\")\n                    productRepository.getAllProducts().collect { products ->\n                        allProducts.clear()\n                        allProducts.addAll(products)\n                        _productsState.emit(UiState.Success(products))\n                    }\n                }\n                updateCacheSize()\n            } catch (e: Exception) {\n                _productsState.emit(UiState.Error(e.message ?: \"Error loading products\"))\n                logError(\"Error loading products: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Load more products (pagination/lazy loading)\n     */\n    fun loadMoreProducts() {\n        viewModelScope.launch {\n            if (_isLoadingMore.value) return@launch\n\n            _isLoadingMore.emit(true)\n            try {\n                val nextPage = _currentPage.value + 1\n                val offset = nextPage * pageSize\n\n                logInfo(\"Loading page $nextPage with offset $offset\")\n                productRepository.getAllProducts().collect { products ->\n                    if (products.size > offset) {\n                        val newProducts = products.drop(offset).take(pageSize)\n                        allProducts.addAll(newProducts)\n                        _currentPage.emit(nextPage)\n                        _productsState.emit(UiState.Success(allProducts.toList()))\n                    }\n                }\n            } catch (e: Exception) {\n                logError(\"Error loading more products: ${e.message}\")\n            } finally {\n                _isLoadingMore.emit(false)\n            }\n        }\n    }\n\n    /**\n     * Check if should load next page based on scroll position\n     */\n    fun checkAndLoadNextPage(currentIndex: Int, totalItems: Int) {\n        if (enhancedProductRepository.shouldLoadNextPage(currentIndex, totalItems)) {\n            loadMoreProducts()\n        }\n    }\n\n    /**\n     * Select category and filter products\n     */\n    fun selectCategory(category: String) {\n        viewModelScope.launch {\n            _selectedCategory.emit(category)\n            _productsState.emit(UiState.Loading)\n            _currentPage.emit(0)\n            allProducts.clear()\n\n            try {\n                if (category.lowercase() == \"all\" || category.lowercase() == \"popular\") {\n                    loadProductsWithCache()\n                } else {\n                    logInfo(\"Filtering by category: $category\")\n                    productRepository.searchByCategory(category).collect { products ->\n                        allProducts.clear()\n                        allProducts.addAll(products)\n                        _productsState.emit(UiState.Success(products))\n                    }\n                }\n            } catch (e: Exception) {\n                _productsState.emit(UiState.Error(e.message ?: \"Error loading category\"))\n                logError(\"Error loading category: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Search products\n     */\n    fun searchProducts(query: String) {\n        viewModelScope.launch {\n            if (query.isBlank()) {\n                loadProductsWithCache()\n            } else {\n                _productsState.emit(UiState.Loading)\n                _currentPage.emit(0)\n                allProducts.clear()\n\n                try {\n                    logInfo(\"Searching for: $query\")\n                    productRepository.searchProducts(query).collect { products ->\n                        allProducts.clear()\n                        allProducts.addAll(products)\n                        _productsState.emit(UiState.Success(products))\n                    }\n                } catch (e: Exception) {\n                    _productsState.emit(UiState.Error(e.message ?: \"Error searching products\"))\n                    logError(\"Error searching products: ${e.message}\")\n                }\n            }\n        }\n    }\n\n    /**\n     * Search by location\n     */\n    fun searchByLocation(location: String) {\n        viewModelScope.launch {\n            if (location.isBlank()) {\n                loadProductsWithCache()\n            } else {\n                _productsState.emit(UiState.Loading)\n                _currentPage.emit(0)\n                allProducts.clear()\n\n                try {\n                    logInfo(\"Searching by location: $location\")\n                    productRepository.searchByLocation(location).collect { products ->\n                        allProducts.clear()\n                        allProducts.addAll(products)\n                        _productsState.emit(UiState.Success(products))\n                    }\n                } catch (e: Exception) {\n                    _productsState.emit(UiState.Error(e.message ?: \"Error searching by location\"))\n                    logError(\"Error searching by location: ${e.message}\")\n                }\n            }\n        }\n    }\n\n    /**\n     * Clear cache\n     */\n    fun clearCache() {\n        viewModelScope.launch {\n            try {\n                enhancedProductRepository.clearProductCache()\n                loadProductsWithCache(forceRefresh = true)\n                logInfo(\"Cache cleared\")\n            } catch (e: Exception) {\n                logError(\"Error clearing cache: ${e.message}\")\n            }\n        }\n    }\n\n    /**\n     * Update cache size display\n     */\n    private fun updateCacheSize() {\n        viewModelScope.launch {\n            val size = enhancedProductRepository.getCacheSize()\n            _cacheSize.emit(size)\n            logInfo(\"Cache size: ${size / 1024} KB\")\n        }\n    }\n}\n
